from typing import List, Any
from dataclasses import dataclass
from os import path, makedirs

from taf.rfrl.l3_call.call_manager import CallManager

from taf.rfrl.procedures.resources.python.bts import CloudBts
from taf.rfrl.procedures.resources.python.bts import ErrorHistory
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_debug
from taf.rfrl.procedures.resources.python.timer.stopwatch import Stopwatch
from taf.rfrl.procedures.cloud.setups_teardowns.log_collection import LogCollector


class EnvVariables:
    """ Represents collection of environment variables which must be available globally during
    test setup, test execution and test teardown. """

    def __init__(self):
        self._variables = {}

    def set(self, name: str, value: Any):
        """
        Sets variable with given name and value.
        If variable with given name already exists then it's old value will be overridden by new value.
        :param name: variable name
        :param value: variable value
        """
        log_debug(f'Setting environment variable {name}={value}')
        self._variables[name] = value

    def get(self, name: str) -> Any:
        """
        Gets value of variable with given name.
        If variable with given name doesn't exist then None will be returned.
        :param name: variable name
        """
        value = self._variables.get(name)
        log_debug(f'Getting environment variable {name}={value}')
        return value

    def remove(self, name: str):
        """
        Removes variable with given name.
        If variable with given name doesn't exist then nothing will happen.
        :param name: variable name
        """
        log_debug(f'Removing environment variable {name}')
        if name in self._variables:
            del self._variables[name]


@dataclass
class TestingEnv:
    """ Represents testing environment containing tested BTSs and common testing tools. """

    gnbs: List[CloudBts]
    enbs: List[CloudBts]
    caller: CallManager
    stopwatch: Stopwatch
    errors: ErrorHistory
    output_dir_path: str
    log_collector: LogCollector
    variables: EnvVariables

    @property
    def btss(self) -> List[CloudBts]:
        """ Returns all BTSs from testing environment in following order: first all gNBs then all eNBS. """
        return self.gnbs + self.enbs

    @property
    def downloads_dir_path(self) -> str:
        """ Returns path to directory where all downloaded files should be stored. If directory doesn't exist yet it is created. """
        downloads_dir_path = f'{self.output_dir_path}/downloads'

        if not path.isdir(downloads_dir_path):
            makedirs(downloads_dir_path)

        return downloads_dir_path
